style.css:
@-moz-document domain("youtube.com") {
/* ========================================
  YouTube Midnight Aurora Skin   A deep dark theme with purple/blue accents
  ======================================== */
  /* --- CSS Variables Override --- */html[dark],
  html {  --yt-spec-base-background: #0d0f1a !important;
    --yt-spec-raised-background: #141728 !important;  --yt-spec-menu-background: #181c30 !important;
    --yt-spec-general-background-a: #0d0f1a !important;  --yt-spec-general-background-b: #141728 !important;
    --yt-spec-general-background-c: #1a1f36 !important;  --yt-spec-brand-background-primary: #0d0f1a !important;
    --yt-spec-brand-background-secondary: #141728 !important;  --yt-spec-text-primary: #e2e4f0 !important;
    --yt-spec-text-secondary: #9ea3c2 !important;  --yt-spec-call-to-action: #9b6dff !important;
    --yt-spec-badge-chip-color: #1e2340 !important;  --yt-spec-icon-active-other: #9b6dff !important;
    --yt-spec-icon-inactive: #6b70a0 !important;  --yt-spec-text-primary-inverse: #0d0f1a !important;
    --yt-spec-10-percent-layer: rgba(155, 109, 255, 0.1) !important;  --yt-spec-static-brand-red: #9b6dff !important;
    --yt-spec-static-brand-white: #e2e4f0 !important;  --yt-spec-outline: #252a4a !important;
  }
  /* --- Page Background --- */html, body,
  ytd-app,[page-subtype="home"],
  ytd-browse,ytd-watch-flexy {
    background: #0d0f1a !important;}
  /* --- Masthead / Top Bar --- */
  #masthead-container,ytd-masthead {
    background: linear-gradient(135deg, #0d0f1a 0%, #161a30 100%) !important;  border-bottom: 1px solid rgba(155, 109, 255, 0.15) !important;
    box-shadow: 0 2px 20px rgba(155, 109, 255, 0.08) !important;}
  /* --- Search Bar --- */
  #search-form,ytd-searchbox #container {
    background: #141728 !important;  border: 1px solid #252a4a !important;
    border-radius: 24px !important;  transition: border-color 0.3s ease !important;
  }
  #search-form:focus-within,ytd-searchbox #container:focus-within {
    border-color: #9b6dff !important;  box-shadow: 0 0 12px rgba(155, 109, 255, 0.2) !important;
  }
  ytd-searchbox #search-icon-legacy {  background: linear-gradient(135deg, #7c4dff, #9b6dff) !important;
    border: none !important;  border-radius: 0 24px 24px 0 !important;
  }
  /* --- Sidebar / Guide --- */ytd-guide-renderer,
  tp-yt-app-drawer,#guide-inner-content {
    background: #0d0f1a !important;  border-right: 1px solid rgba(155, 109, 255, 0.1) !important;
  }
  ytd-guide-entry-renderer[active] {  background: linear-gradient(90deg, rgba(155, 109, 255, 0.15), transparent) !important;
    border-radius: 12px !important;}
  ytd-guide-entry-renderer:hover {
    background: rgba(155, 109, 255, 0.08) !important;  border-radius: 12px !important;
  }
  /* --- Chip Bar (Home page filter buttons) --- */yt-chip-cloud-chip-renderer,
  ytd-feed-filter-chip-bar-renderer #chips yt-chip-cloud-chip-renderer {  background: #1a1f36 !important;
    border: 1px solid #252a4a !important;  border-radius: 20px !important;
    color: #9ea3c2 !important;  transition: all 0.3s ease !important;
  }
  yt-chip-cloud-chip-renderer:hover {  background: rgba(155, 109, 255, 0.15) !important;
    border-color: #9b6dff !important;  color: #e2e4f0 !important;
  }
  yt-chip-cloud-chip-renderer[selected] {  background: linear-gradient(135deg, #7c4dff, #9b6dff) !important;
    border-color: transparent !important;  color: #ffffff !important;
  }
  /* --- Video Thumbnails / Cards --- */ytd-rich-item-renderer,
  ytd-compact-video-renderer,ytd-video-renderer {
    transition: transform 0.2s ease, box-shadow 0.2s ease !important;}
  ytd-rich-item-renderer:hover,
  ytd-compact-video-renderer:hover,ytd-video-renderer:hover {
    transform: translateY(-2px) !important;}
  ytd-thumbnail {
    border-radius: 12px !important;  overflow: hidden !important;
  }
  ytd-thumbnail #thumbnail img {  border-radius: 12px !important;
  }
  /* --- Video Title Links --- */#video-title,
  h3.ytd-rich-grid-media a,a.yt-simple-endpoint.ytd-rich-grid-media {
    color: #e2e4f0 !important;  transition: color 0.2s ease !important;
  }
  #video-title:hover {  color: #c4a3ff !important;
  }
  /* --- Channel Name & Metadata --- */#channel-name a,
  #metadata-line span,.ytd-channel-name a {
    color: #8b90b8 !important;}
  #channel-name a:hover {
    color: #9b6dff !important;}
  /* --- Subscribe Button --- */
  #subscribe-button ytd-subscribe-button-renderer button,ytd-subscribe-button-renderer tp-yt-paper-button {
    background: linear-gradient(135deg, #7c4dff, #9b6dff) !important;  border: none !important;
    border-radius: 24px !important;  color: #ffffff !important;
    text-transform: uppercase !important;  font-weight: 600 !important;
    letter-spacing: 0.5px !important;  transition: all 0.3s ease !important;
  }
  #subscribe-button ytd-subscribe-button-renderer button:hover {  background: linear-gradient(135deg, #9b6dff, #b388ff) !important;
    box-shadow: 0 4px 15px rgba(155, 109, 255, 0.4) !important;}
  /* --- Like / Dislike / Share Buttons --- */
  ytd-menu-renderer yt-icon-button,ytd-toggle-button-renderer button,
  #top-level-buttons-computed ytd-toggle-button-renderer {  color: #9ea3c2 !important;
    transition: color 0.2s ease !important;}
  ytd-toggle-button-renderer:hover button {
    color: #9b6dff !important;}
  /* --- Video Player Area --- */
  #player-theater-container,#full-bleed-container {
    background: #0a0c16 !important;}
  /* --- Comments Section --- */
  ytd-comments #header,ytd-comment-thread-renderer {
    border-color: rgba(155, 109, 255, 0.08) !important;}
  ytd-comment-renderer #body {
    color: #c8cbe0 !important;}
  ytd-comment-renderer #author-text {
    color: #9b6dff !important;}
  #comment-input ytd-commentbox #creation-box {
    background: #141728 !important;  border: 1px solid #252a4a !important;
    border-radius: 12px !important;  color: #e2e4f0 !important;
  }
  /* --- Scrollbar Styling --- */::-webkit-scrollbar {
    width: 8px !important;}
  ::-webkit-scrollbar-track {
    background: #0d0f1a !important;}
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #7c4dff, #5c3aab) !important;  border-radius: 10px !important;
  }
  ::-webkit-scrollbar-thumb:hover {  background: linear-gradient(180deg, #9b6dff, #7c4dff) !important;
  }
  /* --- Popup Menus / Dropdowns --- */tp-yt-iron-dropdown,
  ytd-menu-popup-renderer,tp-yt-paper-listbox {
    background: #181c30 !important;  border: 1px solid rgba(155, 109, 255, 0.15) !important;
    border-radius: 12px !important;  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5) !important;
  }
  tp-yt-paper-item:hover {  background: rgba(155, 109, 255, 0.1) !important;
  }
  /* --- Notifications Panel --- */ytd-multi-page-menu-renderer {
    background: #141728 !important;  border: 1px solid rgba(155, 109, 255, 0.12) !important;
  }
  /* --- Right Sidebar on Watch Page --- */ytd-compact-video-renderer {
    background: transparent !important;  border-radius: 8px !important;
    padding: 4px !important;}
  ytd-compact-video-renderer:hover {
    background: rgba(155, 109, 255, 0.06) !important;}
  /* --- Playlist Panel --- */
  ytd-playlist-panel-renderer {  background: #141728 !important;
    border-radius: 12px !important;  border: 1px solid rgba(155, 109, 255, 0.1) !important;
  }
  /* --- Buttons General --- */yt-button-renderer a.yt-simple-endpoint,
  tp-yt-paper-button {  border-radius: 20px !important;
    transition: all 0.2s ease !important;}
  /* --- Links --- */
  a.yt-simple-endpoint:hover {  color: #c4a3ff !important;
  }
  /* --- Loading Bar Override --- */yt-page-navigation-progress {
    background: linear-gradient(90deg, #7c4dff, #9b6dff, #b388ff) !important;}
  /* --- Selection Color --- */
  ::selection {  background: rgba(155, 109, 255, 0.3) !important;
    color: #ffffff !important;}
}
